import React from 'react';

import PohAva from '@ui-kit/Ava';

import WorkoutListItem from '.';
import { IWorkout } from '../@types/workouts.types';

interface IWorkoutListGroupProps {
  workouts: IWorkout[];
}

const WorkoutListGroup: React.FC<IWorkoutListGroupProps> = ({ workouts }) => {
  const data = workouts[0];

  return (
    <WorkoutListItem
      data={data}
      name={
        <div>
          <small className="text-success" style={{ fontSize: 8 }}>
            Совместная тренировка
          </small>
          <strong className="d-block mt-n1">{data.group?.name}</strong>
        </div>
      }
      last={
        <>
          {workouts.map((w, i) => {
            return (
              <PohAva
                key={w.id}
                src={w.user.photo}
                alt={w.user.name}
                className={i !== workouts.length - 1 ? 'me-n2' : ''}
                title={[w.user.name, new Date(w.date_upload).toLocaleString()].join(' ')}
              />
            );
          })}
        </>
      }
    />
  );
};

export default WorkoutListGroup;
